/*
 * A329142  Numbers whose prime signature is not a necklace.
 * https://oeis.org/A329142
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 57, u16 n <= 57, u32 n <= 57, u64 n <= 57, u128 n <= 57,
 *            big any n
 * Helpers:   not_necklace
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: Numbers whose prime signature is not a necklace (OEIS A329142) *
 * The sequence is generated by iterating over natural numbers, computing
 * their prime factorization in ascending prime order, and keeping those
 * whose exponent sequence is NOT lexicographically minimal among its
 * cyclic rotations.  The result is cached to allow arbitrary index access. */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/not_necklace.h"

/* Build primes up to limit (inclusive) using a simple sieve */
static void build_primes_upto(unsigned long long limit,
                             uint32_t **primes_out, size_t *cnt_out)
{
    unsigned char *is_composite = (unsigned char *)calloc(limit + 1, 1);
    size_t capacity = limit / 10 + 1;
    uint32_t *primes = (uint32_t *)malloc(capacity * sizeof(uint32_t));
    size_t count = 0;

    for (unsigned long long p = 2; p <= limit; ++p) {
        if (!is_composite[p]) {
            if (count == capacity) {
                capacity *= 2;
                primes = (uint32_t *)realloc(primes, capacity * sizeof(uint32_t));
            }
            primes[count++] = (uint32_t)p;
            if (p * p <= limit) {
                for (unsigned long long q = p * p; q <= limit; q += p)
                    is_composite[q] = 1;
            }
        }
    }
    free(is_composite);
    *primes_out = primes;
    *cnt_out = count;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    static uint32_t *primes = NULL;
    static size_t prime_cnt = 0;
    static seq_t *terms = NULL;
    static size_t terms_len = 0;
    static size_t terms_cap = 0;
    static idx_t last_checked = 0;        /* largest integer processed so far */

    /* Initialise primes once (sieve up to 200000) */
    if (!primes) {
        build_primes_upto(200000, &primes, &prime_cnt);
    }

    /* Initialise terms array once */
    if (!terms) {
        terms_cap = 1024;
        terms = (seq_t *)malloc(terms_cap * sizeof(seq_t));
    }

    /* Generate terms until we reach the desired index n */
    while (terms_len < (size_t)n) {
        idx_t x = last_checked + 1;

        /* Factorise x, collecting exponents in ascending prime order */
        unsigned long long temp = (unsigned long long)x;
        int exps[64];
        int exps_cnt = 0;
        for (size_t i = 0; i < prime_cnt && (unsigned long long)primes[i] * primes[i] <= temp; ++i) {
            int cnt = 0;
            while (temp % primes[i] == 0) {
                temp /= primes[i];
                ++cnt;
            }
            if (cnt > 0) exps[exps_cnt++] = cnt;
        }
        if (temp > 1) exps[exps_cnt++] = 1;   /* residual prime factor */

        /* Check whether this number has a non‑necklace signature */
        if (not_necklace(exps, exps_cnt)) {
            /* Append to cache if needed */
            if (terms_len == terms_cap) {
                terms_cap *= 2;
                terms = (seq_t *)realloc(terms, terms_cap * sizeof(seq_t));
            }
            terms[terms_len++] = (seq_t)x;
        }
        last_checked = x;
    }

    return terms[(size_t)n - 1];
}
